-- ---------------------------------------------------------------- profiles: one SELECT policy instead of two permissive ones
-- Same rule (own profile, or ADMIN sees all), evaluated once per row (advisor: multiple_permissive_policies).
drop policy profiles_admin on cw_prod.profiles;
drop policy profiles_self on cw_prod.profiles;
create policy profiles_read on cw_prod.profiles for select to authenticated
  using (id = (select auth.uid()) or (select cw_prod_private.is_admin()));

-- ---------------------------------------------------------------- internal tables: deny-all is intentional
-- audit_logs and job_runs have no grant and no policy for API roles: they are read and written only by SECURITY
-- DEFINER functions (audit trail, admin views) and by service_role jobs. FORCE makes the table owner obey RLS too.
alter table cw_prod.job_runs force row level security;
comment on table cw_prod.audit_logs is 'Append-only audit trail. No API grant and no RLS policy on purpose (deny-all); read through admin RPCs only.';
comment on table cw_prod.job_runs is 'Scheduled job bookkeeping. No API grant and no RLS policy on purpose (deny-all); service_role only.';

